def render_requirements_html(data: dict) -> str:
    """Render requirements report HTML from build_requirements_summary() data."""
    version = data.get("version", 1)
    project = data.get("project", {})
    epics = data.get("epics", [])
    stories = data.get("stories", [])
    roadmap = data.get("roadmap", {})
    sprints = data.get("sprints", [])
    priority_dist = data.get("priority_distribution", {})
    changelog = data.get("changelog", {})
    now = _timestamp_now()
    locked = data.get("locked", False)

    # ── 1. Header
    header = f'''
  <div class="header">
    <div>
      <h1>Requirements Report — <span>{escape(project.get("name", "Project"))}</span></h1>
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
        {_badge(f"v{version}", "badge-version")}
        {_locked_badge(locked)}
        <span class="badge badge-type">{escape(now)}</span>
      </div>
    </div>
  </div>'''

    # ── 2. BRD Summary card
    scope = escape(project.get("scope", "N/A"))
    stakeholders = escape(project.get("stakeholders", "N/A"))
    brd_card = f'''
  <div class="section">
    <div class="section-title">BRD Summary</div>
    <div class="card" style="margin-bottom:16px">
      <div class="card-label">Scope</div>
      <div style="font-size:13px;margin-bottom:12px">{scope}</div>
      <div class="card-label">Stakeholders</div>
      <div style="font-size:13px">{stakeholders}</div>
    </div>
  </div>'''

    # ── 3. Epics table
    epic_rows = ""
    for ep in epics:
        epic_rows += f'''<tr>
          <td>{escape(str(ep.get("id", "")))}</td>
          <td>{escape(ep.get("title", ""))}</td>
          <td>{ep.get("features", 0)}</td>
          <td>{ep.get("stories", 0)}</td>
        </tr>'''
    epics_section = f'''
  <div class="section">
    <div class="section-title">Epics ({len(epics)})</div>
    <table class="data-table">
      <thead><tr><th>ID</th><th>Title</th><th>Features</th><th>Stories</th></tr></thead>
      <tbody>{epic_rows}</tbody>
    </table>
  </div>'''

    # ── 4. Stories inventory grouped by feature
    features: dict[str, list] = {}
    for story in stories:
        feat = story.get("feature", "Ungrouped")
        features.setdefault(feat, []).append(story)

    story_sections = ""
    for feat_name, feat_stories in features.items():
        rows = ""
        for st in feat_stories:
            rows += f'''<tr class="story-row">
              <td>{escape(str(st.get("id", "")))}</td>
              <td>{escape(st.get("title", ""))}</td>
              <td>{_size_badge(st.get("size", ""))}</td>
              <td>{_priority_badge(st.get("priority", ""))}</td>
              <td>{escape(str(st.get("sprint", "")))}</td>
              <td>{_status_badge(st.get("status", "TODO"))}</td>
            </tr>'''
        story_sections += f'''
    <details open>
      <summary style="cursor:pointer;font-weight:600;margin-bottom:8px;font-size:13px">{escape(feat_name)} ({len(feat_stories)} stories)</summary>
      <table class="data-table">
        <thead><tr><th>ID</th><th>Title</th><th>Size</th><th>Priority</th><th>Sprint</th><th>Status</th></tr></thead>
        <tbody>{rows}</tbody>
      </table>
    </details>'''

    stories_section = f'''
  <div class="section">
    <div class="section-title">Stories Inventory ({len(stories)})</div>
    {story_sections}
  </div>'''

    # ── 5. Backlog summary — priority distribution
    must_count = priority_dist.get("Must", 0)
    should_count = priority_dist.get("Should", 0)
    could_count = priority_dist.get("Could", 0)
    total_hours = data.get("total_review_hours", 0)
    backlog_section = f'''
  <div class="section">
    <div class="section-title">Backlog Summary</div>
    <div class="summary">
      <div class="card"><div class="card-label">Must Have</div><div class="card-value">{must_count}</div></div>
      <div class="card"><div class="card-label">Should Have</div><div class="card-value">{should_count}</div></div>
      <div class="card"><div class="card-label">Could Have</div><div class="card-value">{could_count}</div></div>
      <div class="card"><div class="card-label">Review Hours</div><div class="card-value">{total_hours}</div></div>
    </div>
  </div>'''

    # ── 6. Roadmap
    roadmap_html = ""
    if roadmap:
        params = roadmap.get("planning_parameters", "")
        timeline = roadmap.get("timeline_summary", "")
        roadmap_html = f'''
  <div class="section">
    <div class="section-title">Roadmap</div>
    <div class="card" style="margin-bottom:12px">
      <div class="card-label">Planning Parameters</div>
      <div style="font-size:13px">{escape(str(params))}</div>
    </div>
    <div class="card">
      <div class="card-label">Timeline Summary</div>
      <div style="font-size:13px">{escape(str(timeline))}</div>
    </div>
  </div>'''

    # ── 7. Sprint plan
    sprint_html = ""
    if sprints:
        current = sprints[0]
        sprint_goal = escape(current.get("goal", "N/A"))
        sprint_stories_list = current.get("stories", [])
        sprint_capacity = current.get("capacity", "N/A")
        sprint_rows = ""
        for ss in sprint_stories_list:
            sprint_rows += f'<tr><td>{escape(str(ss.get("id", "")))}</td><td>{escape(ss.get("title", ""))}</td></tr>'
        sprint_html = f'''
  <div class="section">
    <div class="section-title">Sprint Plan</div>
    <div class="card" style="margin-bottom:12px">
      <div class="card-label">Goal</div>
      <div style="font-size:13px">{sprint_goal}</div>
      <div class="card-label" style="margin-top:8px">Capacity</div>
      <div style="font-size:13px">{escape(str(sprint_capacity))}</div>
    </div>
    <table class="data-table">
      <thead><tr><th>Story ID</th><th>Title</th></tr></thead>
      <tbody>{sprint_rows}</tbody>
    </table>
  </div>'''

    # ── 8. Changelog
    changelog_html = ""
    cl_items = changelog.get("items", []) if changelog else []
    if cl_items:
        cl_rows = ""
        for ci in cl_items:
            cl_rows += f'''<div class="changelog-item changelog-{escape(ci.get('type', 'modified'))}">
              <span class="badge badge-type">{escape(ci.get("type", "modified"))}</span>
              <span>{escape(ci.get("description", ""))}</span>
            </div>'''
        changelog_html = f'''
  <div class="section">
    <div class="section-title">Changelog</div>
    {cl_rows}
  </div>'''

    # ── 9. Footer
    footer = f'''
  <div class="footer">
    Requirements Report v{version} · Generated {escape(now)}
  </div>'''

    body = header + brd_card + epics_section + stories_section + backlog_section + roadmap_html + sprint_html + changelog_html + footer
    return _html_doc(f"Requirements v{version}", _css_link(1), body)


