# ══════════════════════════════════════════════════════════════════════════════
#  QUALITY HTML RENDERER
# ══════════════════════════════════════════════════════════════════════════════


def render_quality_html(data: dict) -> str:
    """Render quality report HTML from build_sprint_report_data() data."""
    sprint_num = data.get("sprint_num", 1)
    sprint_type = data.get("sprint_type", "dev")
    tests = data.get("tests", {})
    findings = data.get("findings", {})
    remediation = data.get("remediation", {})
    stories = data.get("stories", {})
    now = _timestamp_now()
    locked = data.get("locked", False)

    # ── 1. Header
    header = f'''
  <div class="header">
    <div>
      <h1>Quality Report — <span>Sprint {sprint_num}</span></h1>
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
        {_badge(sprint_type.upper(), "badge-mode")}
        {_locked_badge(locked)}
        <span class="badge badge-type">{escape(now)}</span>
      </div>
    </div>
  </div>'''

    # ── 2. Summary cards grid
    total_tests = tests.get("total", 0)
    passed = tests.get("passed", 0)
    failed = tests.get("failed", 0)
    coverage = tests.get("coverage", "N/A")
    cards = f'''
  <div class="summary">
    <div class="card"><div class="card-label">Tests Total</div><div class="card-value">{total_tests}</div></div>
    <div class="card"><div class="card-label">Passed</div><div class="card-value" style="color:var(--green)">{passed}</div></div>
    <div class="card"><div class="card-label">Failed</div><div class="card-value" style="color:var(--red)">{failed}</div></div>
    <div class="card"><div class="card-label">Coverage</div><div class="card-value">{escape(str(coverage))}</div></div>
  </div>'''

    # ── 3. Test results by category
    categories = tests.get("categories", {})
    cat_html = ""
    if categories:
        cat_rows = ""
        for cat_name, cat_data in categories.items():
            cat_rows += f'''<tr>
              <td>{escape(cat_name)}</td>
              <td>{cat_data.get("total", 0)}</td>
              <td style="color:var(--green)">{cat_data.get("passed", 0)}</td>
              <td style="color:var(--red)">{cat_data.get("failed", 0)}</td>
            </tr>'''
        cat_html = f'''
  <div class="section">
    <div class="section-title">Test Results by Category</div>
    <table class="data-table">
      <thead><tr><th>Category</th><th>Total</th><th>Passed</th><th>Failed</th></tr></thead>
      <tbody>{cat_rows}</tbody>
    </table>
  </div>'''

    # ── 4. Story AC Traceability table
    status_by_story = stories.get("status_by_story", [])
    ac_html = ""
    if status_by_story:
        ac_rows = ""
        for st in status_by_story:
            ac_rows += f'''<tr class="ac-trace-row">
              <td>{escape(str(st.get("id", "")))}</td>
              <td>{escape(st.get("title", ""))}</td>
              <td>{st.get("acceptance_criteria", 0)}</td>
              <td>{_status_badge(st.get("status", "TODO"))}</td>
            </tr>'''
        ac_html = f'''
  <div class="section">
    <div class="section-title">Story AC Traceability</div>
    <table class="data-table">
      <thead><tr><th>Story ID</th><th>Title</th><th>ACs</th><th>Status</th></tr></thead>
      <tbody>{ac_rows}</tbody>
    </table>
  </div>'''

    # ── 5. Regression results (Sprint 2+)
    regression_html = ""
    regression = data.get("regression", {})
    if sprint_num > 1 and regression:
        reg_passed = regression.get("passed", 0)
        reg_failed = regression.get("failed", 0)
        reg_total = regression.get("total", 0)
        regression_html = f'''
  <div class="section">
    <div class="section-title">Regression Results</div>
    <div class="summary">
      <div class="card"><div class="card-label">Total</div><div class="card-value">{reg_total}</div></div>
      <div class="card"><div class="card-label">Passed</div><div class="card-value" style="color:var(--green)">{reg_passed}</div></div>
      <div class="card"><div class="card-label">Failed</div><div class="card-value" style="color:var(--red)">{reg_failed}</div></div>
    </div>
  </div>'''

    # ── 6. Findings section — reuse _html_findings pattern
    finding_items = findings.get("items", [])
    findings_html = ""
    if finding_items:
        counts: dict[str, int] = {}
        open_count = fixed_count = 0
        for fi in finding_items:
            sev = fi.get("severity", "low")
            counts[sev] = counts.get(sev, 0) + 1
            if fi.get("status") == "fixed":
                fixed_count += 1
            else:
                open_count += 1

        btns = '<button class="filter-btn active" data-sev="all" onclick="filterFindings(\'all\')">All</button>'
        if open_count:
            btns += f'<button class="filter-btn" data-sev="open" onclick="filterFindings(\'open\')">Open ({open_count})</button>'
        if fixed_count:
            btns += f'<button class="filter-btn" data-sev="fixed" onclick="filterFindings(\'fixed\')">Fixed ({fixed_count})</button>'
        for sev in ["critical", "high", "medium", "low"]:
            if sev in counts:
                btns += f'<button class="filter-btn" data-sev="{sev}" onclick="filterFindings(\'{sev}\')">{sev.capitalize()} ({counts[sev]})</button>'

        item_html = ""
        for fi in finding_items:
            sev = fi.get("severity", "low")
            color = SEV_COLOR.get(sev, "#6b7280")
            status = fi.get("status", "open")
            status_css = "fixed" if status == "fixed" else ""
            status_badge_html = '<span class="status-fixed">Fixed</span>' if status == "fixed" else '<span class="status-open">Open</span>'
            ref = f'<span>{escape(fi["file_ref"])}</span>' if fi.get("file_ref") else ""
            fid = f'<span>{escape(fi.get("id", ""))}</span>' if fi.get("id") else ""

            item_html += f'''
        <div class="finding-item {status_css}" data-sev="{sev}" data-status="{status}">
          <div class="sev-dot" style="background:{color}"></div>
          <div>
            <div class="finding-title">{escape(fi.get("title", ""))}</div>
            <div class="finding-meta">
              <span style="color:{color};background:transparent;font-weight:600">{sev.capitalize()}</span>
              {status_badge_html}{fid}{ref}
            </div>
          </div>
        </div>'''

        findings_html = f'''
  <div class="section">
    <div class="section-title">Findings ({len(finding_items)})</div>
    <div class="findings-filter">{btns}</div>
    {item_html}
  </div>'''

    # ── 7. Remediation status
    fixed_rem = remediation.get("fixed", 0)
    remaining_rem = remediation.get("remaining", 0)
    remediation_html = f'''
  <div class="section">
    <div class="section-title">Remediation Status</div>
    <div class="summary">
      <div class="card"><div class="card-label">Fixed</div><div class="card-value" style="color:var(--green)">{fixed_rem}</div></div>
      <div class="card"><div class="card-label">Remaining</div><div class="card-value" style="color:var(--orange)">{remaining_rem}</div></div>
    </div>
  </div>''' if (fixed_rem or remaining_rem) else ""

    # ── 8. NFR Results (hardening sprints only)
    nfr_html = ""
    nfr_section = data.get("nfr_section", {})
    if sprint_type == "hardening" and nfr_section:
        nfr_rows = ""
        for nfr_name, nfr_data in nfr_section.items():
            target = escape(str(nfr_data.get("target", "")))
            actual = escape(str(nfr_data.get("actual", "")))
            nfr_status = "PASS" if nfr_data.get("pass", False) else "FAIL"
            nfr_rows += f'''<tr>
              <td>{escape(nfr_name)}</td>
              <td>{target}</td>
              <td>{actual}</td>
              <td>{_status_badge(nfr_status)}</td>
            </tr>'''
        nfr_html = f'''
  <div class="section">
    <div class="section-title">NFR Results</div>
    <table class="data-table">
      <thead><tr><th>Requirement</th><th>Target</th><th>Actual</th><th>Status</th></tr></thead>
      <tbody>{nfr_rows}</tbody>
    </table>
  </div>'''

    # ── 9. Footer
    footer = f'''
  <div class="footer">
    Quality Report — Sprint {sprint_num} · Generated {escape(now)}
  </div>'''

    # JS for findings filter
    js_block = f'<script>{JS}</script>' if finding_items else ""

    body = header + cards + cat_html + ac_html + regression_html + findings_html + remediation_html + nfr_html + footer
    html = _html_doc(f"Quality - Sprint {sprint_num}", _css_link(2), body)
    # Inject JS before closing body if findings exist
    if js_block:
        html = html.replace("</body>", f"{js_block}\n</body>")
    return html


