def render_progress_html(data: dict) -> str:
    """Render progress report HTML from build_sprint_report_data() data."""
    sprint_num = data.get("sprint_num", 1)
    sprint_type = data.get("sprint_type", "dev")
    sprint_goal = data.get("sprint_goal", "")
    stories = data.get("stories", {})
    velocity = data.get("velocity", {})
    burndown = data.get("burndown_data", [])
    backlog_health = data.get("backlog_health", {})
    risks = data.get("risks", [])
    human_feedback = data.get("human_feedback", "")
    next_sprint = data.get("next_sprint", {})
    now = _timestamp_now()
    locked = data.get("locked", False)

    planned = stories.get("planned", 0)
    completed = stories.get("completed", 0)
    blocked = stories.get("blocked", 0)
    completion_pct = round((completed / planned * 100) if planned else 0)

    # ── 1. Header
    header = f'''
  <div class="header">
    <div>
      <h1>Progress Report — <span>Sprint {sprint_num}</span></h1>
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
        {_badge(sprint_type.upper(), "badge-mode")}
        {_locked_badge(locked)}
        <span class="badge badge-type">{escape(now)}</span>
      </div>
    </div>
  </div>'''

    # ── 2. Sprint Summary card
    summary_card = f'''
  <div class="section">
    <div class="section-title">Sprint Summary</div>
    <div class="card" style="margin-bottom:16px">
      <div class="card-label">Goal</div>
      <div style="font-size:14px;font-weight:600;margin-bottom:12px">{escape(sprint_goal)}</div>
      <div class="summary" style="margin-bottom:0">
        <div><div class="card-label">Completion</div><div class="card-value">{completion_pct}%</div></div>
        <div><div class="card-label">Planned</div><div class="card-value">{planned}</div></div>
        <div><div class="card-label">Completed</div><div class="card-value" style="color:var(--green)">{completed}</div></div>
        <div><div class="card-label">Blocked</div><div class="card-value" style="color:var(--red)">{blocked}</div></div>
      </div>
    </div>
  </div>'''

    # ── 3. Story Status table
    status_by_story = stories.get("status_by_story", [])
    story_rows = ""
    for st in status_by_story:
        story_rows += f'''<tr class="story-row">
          <td>{escape(str(st.get("id", "")))}</td>
          <td>{escape(st.get("title", ""))}</td>
          <td>{escape(st.get("feature", ""))}</td>
          <td>{_status_badge(st.get("status", "TODO"))}</td>
          <td>{st.get("files_changed", 0)}</td>
        </tr>'''
    stories_section = f'''
  <div class="section">
    <div class="section-title">Story Status ({len(status_by_story)})</div>
    <table class="data-table">
      <thead><tr><th>ID</th><th>Title</th><th>Feature</th><th>Status</th><th>Files Changed</th></tr></thead>
      <tbody>{story_rows}</tbody>
    </table>
  </div>''' if status_by_story else ""

    # ── 4. Velocity metric
    velocity_html = ""
    if velocity:
        points = velocity.get("points_completed", 0)
        stories_done = velocity.get("stories_completed", 0)
        velocity_html = f'''
  <div class="section">
    <div class="section-title">Velocity</div>
    <div class="summary">
      <div class="card velocity-metric"><div class="card-label">Points Completed</div><div class="card-value">{points}</div></div>
      <div class="card velocity-metric"><div class="card-label">Stories Completed</div><div class="card-value">{stories_done}</div></div>
    </div>
  </div>'''

    # ── 5. Burn-down chart
    burndown_html = ""
    if burndown:
        bars = ""
        max_total = max((b.get("total", 1) for b in burndown), default=1) or 1
        for b in burndown:
            s_label = escape(str(b.get("sprint", "")))
            done_val = b.get("done", 0)
            remaining_val = b.get("remaining", 0)
            done_pct = round(done_val / max_total * 100)
            remaining_pct = round(remaining_val / max_total * 100)
            bars += f'''
        <div style="margin-bottom:8px">
          <div style="font-size:12px;color:var(--muted);margin-bottom:4px">{s_label}</div>
          <div style="display:flex;height:24px;border-radius:6px;overflow:hidden;background:var(--surface2)">
            <div class="burndown-bar-done" style="width:{done_pct}%;background:var(--green)"></div>
            <div class="burndown-bar-remaining" style="width:{remaining_pct}%;background:var(--orange)"></div>
          </div>
          <div style="font-size:11px;color:var(--muted);margin-top:2px">{done_val} done · {remaining_val} remaining</div>
        </div>'''
        burndown_html = f'''
  <div class="section">
    <div class="section-title">Burn-down</div>
    <div class="card">{bars}</div>
  </div>'''

    # ── 6. Backlog Health
    backlog_html = ""
    if backlog_health:
        bl_total = backlog_health.get("total", 0)
        bl_done = backlog_health.get("done", 0)
        bl_todo = backlog_health.get("todo", 0)
        bl_blocked = backlog_health.get("blocked", 0)
        bl_must_remaining = backlog_health.get("must_remaining", 0)
        backlog_html = f'''
  <div class="section">
    <div class="section-title">Backlog Health</div>
    <div class="summary">
      <div class="card"><div class="card-label">Total</div><div class="card-value">{bl_total}</div></div>
      <div class="card"><div class="card-label">Done</div><div class="card-value" style="color:var(--green)">{bl_done}</div></div>
      <div class="card"><div class="card-label">To Do</div><div class="card-value">{bl_todo}</div></div>
      <div class="card"><div class="card-label">Blocked</div><div class="card-value" style="color:var(--red)">{bl_blocked}</div></div>
      <div class="card"><div class="card-label">Must Remaining</div><div class="card-value" style="color:var(--orange)">{bl_must_remaining}</div></div>
    </div>
  </div>'''

    # ── 7. Risks & blockers
    risks_html = ""
    if risks:
        risk_items = ""
        for r in risks:
            risk_items += f'<div class="card" style="margin-bottom:8px"><div style="font-size:13px">{escape(str(r))}</div></div>'
        risks_html = f'''
  <div class="section">
    <div class="section-title">Risks &amp; Blockers</div>
    {risk_items}
  </div>'''

    # ── 8. Human feedback
    feedback_html = ""
    if human_feedback:
        feedback_html = f'''
  <div class="section">
    <div class="section-title">Human Feedback</div>
    <div class="card"><div style="font-size:13px">{escape(str(human_feedback))}</div></div>
  </div>'''

    # ── 9. Next Sprint Plan
    next_html = ""
    if next_sprint:
        next_type = next_sprint.get("type", "dev")
        next_goal = escape(next_sprint.get("goal", ""))
        next_stories_list = next_sprint.get("stories", [])
        next_capacity = escape(str(next_sprint.get("capacity", "N/A")))

        type_label = {
            "hardening": "Next: Hardening",
            "uat": "Next: UAT",
            "complete": "Complete",
        }.get(next_type, f"Next: Sprint {sprint_num + 1}")

        ns_rows = ""
        for ns in next_stories_list:
            ns_rows += f'<tr><td>{escape(str(ns.get("id", "")))}</td><td>{escape(ns.get("title", ""))}</td></tr>'
        ns_table = f'''
    <table class="data-table" style="margin-top:12px">
      <thead><tr><th>Story ID</th><th>Title</th></tr></thead>
      <tbody>{ns_rows}</tbody>
    </table>''' if ns_rows else ""

        next_html = f'''
  <div class="section next-sprint-section">
    <div class="section-title">{escape(type_label)}</div>
    <div class="card">
      <div class="card-label">Goal</div>
      <div style="font-size:13px;margin-bottom:8px">{next_goal}</div>
      <div class="card-label">Capacity</div>
      <div style="font-size:13px">{next_capacity}</div>
    </div>
    {ns_table}
  </div>'''

    # ── 10. Footer
    footer = f'''
  <div class="footer">
    Progress Report — Sprint {sprint_num} · Generated {escape(now)}
  </div>'''

    body = header + summary_card + stories_section + velocity_html + burndown_html + backlog_html + risks_html + feedback_html + next_html + footer
    return _html_doc(f"Progress - Sprint {sprint_num}", _css_link(2), body)


# ══════════════════════════════════════════════════════════════════════════════
#  CHANGELOG HTML RENDERER
# ══════════════════════════════════════════════════════════════════════════════


def render_changelog_html(data: dict, report_type: str, version: int) -> str:
    """Render standalone changelog page."""
    changelog = data.get("changelog", {})
    items = changelog.get("items", []) if changelog else []
    now = _timestamp_now()

    # ── 1. Header
    header = f'''
  <div class="header">
    <div>
      <h1>Changelog — <span>v{version}</span></h1>
      <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
        {_badge(report_type.capitalize(), "badge-mode")}
        <span class="badge badge-type">{escape(now)}</span>
      </div>
    </div>
  </div>'''

    # ── 2. Summary counts
    added = sum(1 for i in items if i.get("type") == "added")
    modified = sum(1 for i in items if i.get("type") == "modified")
    removed = sum(1 for i in items if i.get("type") == "removed")
    summary_html = f'''
  <div class="section">
    <div class="section-title">Summary</div>
    <div class="summary changelog-summary">
      <div class="card"><div class="card-label">Added</div><div class="card-value" style="color:var(--green)">{added}</div></div>
      <div class="card"><div class="card-label">Modified</div><div class="card-value" style="color:var(--yellow)">{modified}</div></div>
      <div class="card"><div class="card-label">Removed</div><div class="card-value" style="color:var(--red)">{removed}</div></div>
    </div>
  </div>'''

    # ── 3. Items grouped by category
    grouped: dict[str, list] = {}
    for item in items:
        cat = item.get("category", "General")
        grouped.setdefault(cat, []).append(item)

    items_html = ""
    for cat_name, cat_items in grouped.items():
        entries = ""
        for ci in cat_items:
            item_type = ci.get("type", "modified")
            entries += f'''<div class="changelog-item changelog-{escape(item_type)}">
              <span class="badge badge-type">{escape(item_type)}</span>
              <span>{escape(ci.get("description", ""))}</span>
            </div>'''
        items_html += f'''
  <div class="section">
    <div class="section-title">{escape(cat_name)}</div>
    {entries}
  </div>'''

    footer = f'''
  <div class="footer">
    Changelog v{version} ({report_type}) · Generated {escape(now)}
  </div>'''

    body = header + summary_html + items_html + footer
    return _html_doc(f"Changelog v{version}", _css_link(1), body)


